فنکشن کی تعریف کا دوسرا حصہ فنکشن کا جسم ہے۔ اس میں وہ اصل بیانات ہوتے ہیں جو مطلوبہ کام انجام دیتے ہیں اور یہ ہمیشہ { } میں بند ہوتا ہے۔

پوری فنکشن کی تعریف ذیل میں دکھائی گئی ہے:

int maximum(int x. int y, int z) // function declarator
{
int max = x;          ┐
if ( y > max )        │
max = y;              │
if ( z > max )        ├ function body
max = z;              │
return max;           ┘
}

c. فنکشن کال

فنکشن کال، کال کرنے والے فنکشن (مثلاً main() فنکشن) میں ایک بیان ہے جو فنکشن کا کوڈ چلاتا ہے۔ درج ذیل بیان پر غور کریں:

maximum( a, b, c );

فنکشن کال میں آرگیومنٹس کی فہرست ہوتی ہے جو فنکشن ڈکلیریٹر کو پاس کی جاتی ہے۔ اس کال میں آرگیومنٹس a، b اور c ہیں۔ درج ذیل پروگرام فنکشن کے مختلف حصے یعنی پروٹوٹائپ، تعریف اور کال دکھاتا ہے۔

// finding maximum out of three integers using function
#include <conio.h>
#include <iostream.h>
int maximum( int, int, int ); // function prototype
int main()
{
int a, b, c;
cout << "Enter three integers: ";
cin >> a >> b >> c;
cout << "Maximum is: " << maximum ( a, b, c ) << endl; // Function call
getch();
return 0;
}
int maximum( int x, int y, int z ) // function definition
{
int max = x;
if ( y > max )
max = y;
if ( z > max )
max = z;
return max;
}

پروگرام کا آؤٹ پٹ

Enter three integers: 4 -2 6
Maximum is: 6

6.1.5 ویری ایبلز کا دائرہ

ویری ایبل کے دائرے سے مراد یہ ہے کہ اگر کسی پروگرام میں ویری ایبل بیان کیا گیا ہو تو اسی پروگرام کے کن حصوں میں اس ویری ایبل تک رسائی ہو سکتی ہے۔ ویری ایبلز کے تین دائرے ہیں۔

